/// Matrix44FromAxisAngle at 0x8041c74c. Caller supplies a normalized axis.
pub fn axis_angle(axis: [f32; 3], angle: f32) -> Matrix {
    let [x, y, z] = axis;
    let (s, c) = crate::character_input::ea_sin_cos(angle);
    let t = 1.0 - c;
    let tx = t * x;
    let ty = t * y;
    let tz = t * z;
    let sx = s * x;
    let sy = s * y;
    let sz = s * z;
    [
        tx.mul_add(x, c),
        tx.mul_add(y, sz),
        tx.mul_add(z, -sy),
        0.,
        ty.mul_add(x, -sz),
        ty.mul_add(y, c),
        ty.mul_add(z, sx),
        0.,
        tz.mul_add(x, sy),
        tz.mul_add(y, -sx),
        tz.mul_add(z, c),
        0.,
        0.,
        0.,
        0.,
        1.,
    ]
}

